import { CornerDownLeftIcon } from 'lucide-react';
import { goItems, matchesTerm, paletteLabels } from '@/components/company-os/command-palette-items';
import type { PaletteItem, PaletteLabels } from '@/components/company-os/command-palette-items';
import { canSee } from '@/components/company-os/nav';
import type { NavGroup } from '@/components/company-os/nav';
import { useRecordSearch } from '@/components/company-os/use-record-search';
import type { RecordSearch } from '@/components/company-os/use-record-search';
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from '@/components/ui/command';
import { Dialog, DialogContent, DialogTitle } from '@/components/ui/dialog';
import { Kbd } from '@/components/ui/kbd';
import { Skeleton } from '@/components/ui/skeleton';

function PaletteGroup({
    heading,
    items,
    onRun,
}: {
    heading: string;
    items: PaletteItem[];
    onRun: (run: PaletteItem['run']) => void;
}) {
    if (items.length === 0) {
        return null;
    }

    return (
        <CommandGroup heading={heading}>
            {items.map((item) => (
                <CommandItem key={item.label} value={`${heading} ${item.label}`} onSelect={() => onRun(item.run)}>
                    <item.icon />
                    {item.label}
                    {item.shortcut && (
                        <span className="ml-auto flex gap-1">
                            {item.shortcut.split(' ').map((key) => (
                                <Kbd key={key}>{key}</Kbd>
                            ))}
                        </span>
                    )}
                </CommandItem>
            ))}
        </CommandGroup>
    );
}

export function CommandPalette({
    open,
    onOpenChange,
    placeholder = 'Search a record or type a command',
    groups,
    permissions,
    actions,
    onSearch,
    onNavigate,
    labels: custom,
}: {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    placeholder?: string;
    groups: NavGroup[];
    permissions: string[];
    actions: PaletteItem[];
    onSearch?: RecordSearch;
    onNavigate: (url: string) => void;
    labels?: Partial<PaletteLabels>;
}) {
    const labels = { ...paletteLabels, ...custom };
    const { query, setQuery, searching, groups: found, failed } = useRecordSearch(onSearch);
    const term = query.trim().toLowerCase();
    const allowedActions = matchesTerm(actions.filter((item) => canSee(item, permissions)), term);
    const allowedGoTo = matchesTerm(goItems(groups, permissions), term);

    const close = () => {
        onOpenChange(false);
        setQuery('');
    };

    const run = (target: PaletteItem['run']) => {
        close();

        if (typeof target === 'function') {
            target();
        } else {
            onNavigate(target);
        }
    };

    return (
        <Dialog open={open} onOpenChange={(next) => (next ? onOpenChange(true) : close())}>
            <DialogContent className="top-24 translate-y-0 gap-0 overflow-hidden p-0 sm:max-w-xl" showCloseButton={false}>
                <DialogTitle className="sr-only">{labels.title}</DialogTitle>
                <Command shouldFilter={false} loop>
                    <CommandInput autoFocus placeholder={placeholder} value={query} onValueChange={setQuery} />
                    <CommandList className="max-h-96">
                        {searching && found.length === 0 && (
                            <div className="grid gap-2 p-2">
                                <Skeleton className="h-7 rounded-md" />
                                <Skeleton className="h-7 rounded-md" />
                            </div>
                        )}
                        {failed && <p className="px-3 py-2 text-sm text-rose-600">{labels.failed}</p>}
                        {found.map((group) => (
                            <CommandGroup key={group.name} heading={group.name}>
                                {group.items.map((item) => (
                                    <CommandItem key={item.id} value={`${group.name} ${item.id}`} onSelect={() => run(item.url)}>
                                        <span className="truncate">{item.label}</span>
                                        <CornerDownLeftIcon className="ml-auto opacity-0 in-data-[selected=true]:opacity-100" />
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                        ))}
                        <PaletteGroup heading={labels.actions} items={allowedActions} onRun={run} />
                        <PaletteGroup heading={labels.goTo} items={allowedGoTo} onRun={run} />
                        {!searching && (
                            <CommandEmpty>
                                {labels.empty} “{query.trim()}”.
                            </CommandEmpty>
                        )}
                    </CommandList>
                </Command>
            </DialogContent>
        </Dialog>
    );
}

import { HouseIcon } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { visibleGroups } from '@/components/company-os/nav';
import type { NavGroup } from '@/components/company-os/nav';
import { toUrl } from '@/lib/navigation';

export type PaletteItem = {
    label: string;
    icon: LucideIcon;
    shortcut?: string;
    permission?: string;
    anyPermission?: string[];
    run: string | (() => void);
};

export type FoundGroup = {
    name: string;
    items: { id: string; label: string; url: string }[];
};

export type PaletteLabels = {
    title: string;
    actions: string;
    goTo: string;
    failed: string;
    empty: string;
};

export const paletteLabels: PaletteLabels = {
    title: 'Command palette',
    actions: 'Actions',
    goTo: 'Go to',
    failed: 'Search failed. Check your connection and type again.',
    empty: 'No records or commands match',
};

export const goItems = (groups: NavGroup[], permissions: string[]): PaletteItem[] =>
    visibleGroups(groups, permissions)
        .flatMap((group) => group.items)
        .map((item) => ({
            label: item.title,
            icon: item.icon ?? HouseIcon,
            shortcut: item.goKey ? `G ${item.goKey.toUpperCase()}` : undefined,
            run: toUrl(item.href),
        }));

export const matchesTerm = (items: PaletteItem[], term: string): PaletteItem[] =>
    items.filter((item) => item.label.toLowerCase().includes(term));

import { useEffect, useRef, useState } from 'react';
import type { FoundGroup } from '@/components/company-os/command-palette-items';

export type RecordSearch = (term: string) => Promise<FoundGroup[]>;

const minLength = 2;
const debounceMs = 200;

export function useRecordSearch(onSearch?: RecordSearch) {
    const [query, setQuery] = useState('');
    const [groups, setGroups] = useState<FoundGroup[]>([]);
    const [searching, setSearching] = useState(false);
    const [failed, setFailed] = useState(false);
    const search = useRef(onSearch);

    useEffect(() => {
        search.current = onSearch;
    }, [onSearch]);

    const term = query.trim();
    const active = term.length >= minLength;

    useEffect(() => {
        if (!active) {
            return;
        }

        let cancelled = false;
        const timer = window.setTimeout(() => {
            const run = search.current;

            if (!run) {
                return;
            }

            setSearching(true);
            setFailed(false);
            run(term)
                .then((found) => {
                    if (!cancelled) {
                        setGroups(found);
                    }
                })
                .catch(() => {
                    if (!cancelled) {
                        setFailed(true);
                    }
                })
                .finally(() => {
                    if (!cancelled) {
                        setSearching(false);
                    }
                });
        }, debounceMs);

        return () => {
            cancelled = true;
            window.clearTimeout(timer);
        };
    }, [term, active]);

    const change = (value: string) => {
        setQuery(value);

        if (value.trim().length < minLength) {
            setGroups([]);
            setFailed(false);
            setSearching(false);
        }
    };

    return { query, setQuery: change, searching, groups: active ? groups : [], failed };
}

import { useEffect, useRef } from 'react';
import { goShortcuts } from '@/components/company-os/nav';
import type { NavGroup } from '@/components/company-os/nav';

export type ShortcutHandlers = {
    groups: NavGroup[];
    permissions: string[];
    onPalette: () => void;
    onQuickCreate: () => void;
    onHelp: () => void;
    onCreate?: () => void;
    onNavigate: (url: string) => void;
};

const goWindowMs = 1200;

const isTyping = (target: EventTarget | null): boolean =>
    target instanceof HTMLElement &&
    (target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName));

const dialogOpen = (): boolean => document.querySelector('[role="dialog"]') !== null;

export function useShortcuts(handlers: ShortcutHandlers) {
    const latest = useRef(handlers);

    useEffect(() => {
        latest.current = handlers;
    }, [handlers]);

    useEffect(() => {
        let awaitingGo = 0;

        const onKey = (event: KeyboardEvent) => {
            const { groups, permissions, onPalette, onQuickCreate, onHelp, onCreate, onNavigate } =
                latest.current;
            const key = event.key.toLowerCase();

            if ((event.metaKey || event.ctrlKey) && key === 'k') {
                event.preventDefault();
                onPalette();

                return;
            }

            if (isTyping(event.target) || dialogOpen() || event.metaKey || event.ctrlKey || event.altKey) {
                return;
            }

            const destination = goShortcuts(groups, permissions).find((shortcut) => shortcut.key === key);

            if (destination && Date.now() - awaitingGo < goWindowMs) {
                awaitingGo = 0;
                event.preventDefault();
                onNavigate(destination.url);

                return;
            }

            if (key === 'g') {
                awaitingGo = Date.now();

                return;
            }

            const single: Record<string, (() => void) | undefined> = {
                '?': onHelp,
                '/': onPalette,
                n: onQuickCreate,
                c: onCreate,
            };
            const handler = single[event.key] ?? single[key];

            if (handler) {
                event.preventDefault();
                handler();
            }
        };

        window.addEventListener('keydown', onKey);

        return () => window.removeEventListener('keydown', onKey);
    }, []);
}
